param([string]$Source='docs/openapi-v13-canonical.json',[string]$Output='docs/openapi-v14-canonical.json')
$ErrorActionPreference='Stop';$d=Get-Content -LiteralPath $Source -Raw -Encoding UTF8|ConvertFrom-Json;$d.info.title='SanSo API V14';$d.info.version='0.14.0-pilot';$d.info.description='Canonical V14 pilot contract. Adds formula-free reconciliation XLSX data packs to the durable preview/checksum/confirm/download lifecycle.';$d.'x-sanso-canonical-entrypoint'='backend/SanSo.Api.V6/ProgramCanonicalV14.cs'
$request=[ordered]@{type='object';required=@('runId');properties=[ordered]@{runId=@{type='string';format='uuid'};type=@{type='string';enum=@('RECONCILIATION_CSV','RECONCILIATION_XLSX');default='RECONCILIATION_CSV'}}};$d.components.schemas.ExportRequest=$request;$d.components.schemas.ExportPreview.properties.type=@{type='string';enum=@('RECONCILIATION_CSV','RECONCILIATION_XLSX')};$d.components.schemas.ExportPreview.properties.contentType=@{type='string';enum=@('text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')};$d.paths.'/api/reports/exports'.post.responses.'200'.description='Durable CSV/XLSX preview requiring checksum confirmation';$d.paths.'/api/reports/exports/{id}/download'.get.responses.'200'.description='Confirmed traceable CSV or formula-free XLSX data pack';$d.paths.'/api/reports/exports/{id}/download'.get.responses.'200'.content|Add-Member 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' @{schema=@{type='string';format='binary'}} -Force
$json=$d|ConvertTo-Json -Depth 100;[System.IO.File]::WriteAllText((Join-Path(Get-Location)$Output),$json+[Environment]::NewLine,[System.Text.UTF8Encoding]::new($false));"OPENAPI_V14_GENERATED=$Output"
